from bisect import bisect_left

def max_nested(boxes: list[list[int]]) -> int:
    order = sorted(boxes, key=lambda b: (b[0], -b[1]))   # same width: tallest first, so they never chain
    tails = []                           # tails[k]: lowest height that ends a chain of k + 1 boxes
    for _, h in order:
        k = bisect_left(tails, h)        # the first chain end that is not below h
        if k == len(tails):
            tails.append(h)              # h extends the longest chain
        else:
            tails[k] = h                 # a lower end for chains of k + 1 boxes
    return len(tails)

perf.naive:
def max_nested(boxes: list[list[int]]) -> int:
    order = sorted(boxes)
    chain = [1] * len(order)             # chain[i]: longest chain ending with box i, from every earlier box
    for i, (w, h) in enumerate(order):
        for j in range(i):
            if order[j][0] < w and order[j][1] < h and chain[j] + 1 > chain[i]:
                chain[i] = chain[j] + 1
    return max(chain, default=0)
